fn has_close_elements(numbers: Vec<f32>, threshold: f32) -> bool {

    for i in 0..numbers.len()-1 {
        for j in (i+1)..numbers.len() {
            let distance:f32 = numbers[i] - numbers[j];
            if distance.abs() < threshold {
                return true;
            }
        }
    }

    return false;
}

