fn intersperse(numbers: Vec<u32>, delimeter: u32) -> Vec<u32> {

    let mut res:Vec<u32> = vec![];
    for item in numbers.iter() {
        res.push(*item);
        if !numbers.is_empty() {
            res.push(delimeter);
        }
    }
    return res;
}

