fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {

    let mut running_max :i32 = i32::MIN;
    let mut result:Vec<i32> = vec![];

    for n in numbers{
        if n > running_max {
            running_max = n;
        }
        result.push(running_max);
    }
    return result;

}

