use std::any::{Any, TypeId};

fn find_closest_elements(numbers: Vec<f32>) -> (f32, f32) {

    let mut closest_pair = (numbers[0], numbers[1]);
    let mut distance: Option<f32> = None;

    for i in 0..numbers.len() {
        for j in i+1..numbers.len() {
            if distance.is_none() || (distance.unwrap() > (numbers[i] - numbers[j]).abs()) {
                distance = Some((numbers[i] - numbers[j]).abs());
                closest_pair = (numbers[i], numbers[j]);
            }
        }
    }
    return closest_pair;
}

