use regex::Regex;
use md5;
use std::any::{Any, TypeId};

fn poly(xs: &Vec<f64>, x: f64) -> f64 {
    let mut sum = 0.0;
    for i in 0..xs.len() {
        sum += xs[i] * x.powi(i as i32);
    }
    sum
}

fn find_zero(xs: &Vec<f64>) -> f64 {
    let mut driv = 0.0;
    let mut ans = 0.0;
    let mut value = poly(xs, ans);
    while value.abs() > 1e-6 {
        for i in 1..xs.len() {
            driv += xs[i] * ans.powi((i - 1) as i32) * (i as f64);
        }
        ans = value - driv / ans;
        value = poly(xs, ans);
    }
    ans
}
