fn modp(n: i32, p: i32) -> i32 {
    if n == 0 {
        return 1;
    } else {
        let result = (modp(n - 2, p) * 2) % p;
        // Ensure the result is within the range [0, p-1]
        if result < 0 {
            result += p;
        }
        return result;
    }
}

