fn monotonic(l: Vec<i32>) -> bool {

    let mut l1:Vec<i32> = l.clone();
    let mut l2:Vec<i32> = l.clone();
    l2.sort(); l2.reverse();
    l1.sort();

    if  l == l1 || l == l2 {return false}

    // Check for duplicates
    let mut seen = HashSet::new();
    for &num in &l {
        if seen.contains(&num) {
            return false;
        }
        seen.insert(num);
    }

    return true;
}
