fn pluck(arr: Vec<i32>) -> Vec<i32> {

    let mut out:Vec<i32> = vec![];

    for i in 0.. arr.len(){
        if arr[i]%2 == 0 && (out.is_empty() || arr[i]<out[0]){
            out = vec![i as i32, arr[i]];
