fn will_it_fly(q: Vec<i32>, w:i32) -> bool{
    if q.iter().sum::<i32>() > w {
        return false;
    }
    let mut i = 0;
    let mut j = q.len() - 1;

    while i < j {
        if q[i] == q[j] {
            return false;
        }
        if q[i] > q[j] {
            replace(&mut q[i], &q[j]);
        } else {
            replace(&mut q[j], &q[i]);
        }
        i += 1;
        j -= 1;
    }
    return true;
}
