fn next_smallest(lst: Vec<i32>) -> i32{
    let mut res = 0;
    let mut lst_cp = lst.clone();
    let mut first: i32 = 1;
    let mut second: i32 = 2;

    if lst.is_empty() {
        res = -1;
    } else {
        if let Some(min_val) = lst.iter().min() {
            first = min_val;
            let indx = lst.iter().position(|x| *x == first).unwrap();
            lst_cp.remove(indx);

            if !lst_cp.is_empty() {
                second = lst_cp.iter().min().unwrap();
            }
            if first != second {
                res = second;
            } else {
                res = -1;
            }
        }
    }
    return res;
}
