fn exchange(lst1: Vec<i32>, lst2: Vec<i32>) -> String{
    let mut even_count1 = 0;
    let mut odd_count1 = 0;
    let mut even_count2 = 0;
    let mut odd_count2 = 0;

    // Count even and odd numbers in both lists
    for &num in lst1.iter() {
        if num % 2 == 0 {
            even_count1 += 1;
        } else {
            odd_count1 += 1;
        }
    }

    for &num in lst2.iter() {
        if num % 2 == 0 {
            even_count2 += 1;
        } else {
            odd_count2 += 1;
        }
    }

    // Check if the number of even numbers in lst1 is greater than or equal to the length of lst2
    if even_count1 >= lst2.len() {
        return "YES".to_string();
    }

    // Check if the number of odd numbers in lst1 is less than or equal to the number of odd numbers in lst2
    if odd_count1 <= odd_count2 {
        return "YES".to_string();
    }

    return "NO".to_string();
}
