        ('t', 19),
        ('u', 20),
        ('v', 21),
        ('w', 22),
        ('x', 23),
        ('y', 24),
        ('z', 25),
    ]);

    if txt.contains(',') {
        out = txt
            .split(',')
            .into_iter()
            .map(|c| c.trim().to_string())
