fn intersection(interval1: Vec<i32>, interval2: Vec<i32>) -> String {

    let inter1 = max(interval1[0], interval2[0]);
    let inter2 = min(interval1[1], interval2[1]);
    let l = inter2 - inter1;

    // Check if the length of the intersection is greater than 1
    if l <= 1 {
        return "NO".to_string();
    }

    // Check if the intersection has any common elements with the original intervals
    for i in 2..l {
        if l % i == 0 {
            return "NO".to_string();
        }
    }

    return "YES".to_string();
