fn can_arrange(arr: Vec<i32>) -> i32 {

    let mut max: i32 = -1;
    for i in 0..arr.len() {
        if arr[i] <= i as i32 {
            max = i as i32;
        }
    }

    // Check if the array is already sorted
    if max == arr.len() - 1 {
        return max;
    }

    // Find the first element that does not follow the pattern
    for i in (0..=max).rev() {
        if arr[i] > i as i32 + 1 {
            // Swap the elements to correct the order
            arr.swap(i, i + 1);
            break;
        }
    }

    // Return the new maximum value
    max += 1;
    return max;
}

