fn simplify(x: &str, n: &str) -> bool {

    let mut a = 0;
    let mut b = 0;
    let mut c = 0;
    let mut d = 0;
    let mut i = 0;

    // Find the first occurrence of '/' in x and y
    while i < x.len() && x.chars().nth(i).unwrap() != '/' {
        i += 1;
    }
    if i >= x.len() {
        return false; // No '/' found in x
    }
    a = x
        .chars()
        .take(i)
        .collect::<String>()
        .parse::<i32>()
        .unwrap();

    while i < n.len() && n.chars().nth(i).unwrap() != '/' {
        i += 1;
    }
    if i >= n.len() {
        return false; // No '/' found in y
    }
    b = n
        .chars()
        .take(i)
        .collect::<String>()
        .parse::<i32>()
        .unwrap();

    // Skip the '/' character after finding it
    i += 1;

    // Continue parsing for the rest of x and y
    while i < x.len() {
        if x.chars().nth(i).unwrap() == '/' {
            c = x
                .chars()
                .take(i)
                .collect::<String>()
                .parse::<i32>()
                .unwrap();
            d = x
                .chars()
                .skip(i + 1)
                .collect::<String>()
                .parse::<i32>()
                .unwrap();
        }
        i += 1;
    }

    // Continue parsing for the rest of n and y
    while i < n.len() {
        if n.chars().nth(i).unwrap() == '/' {
            c = n
                .chars()
                .take(i)
                .collect::<String>()
                .parse::<i32>()
                .unwrap();
            d = n
                .chars()
                .skip(i + 1)
                .collect::<String>()
                .parse::<i32>()
                .unwrap();
        }
        i += 1;
    }

    if (a * b * c) % (b * d) == 0 {
        return true;
    }
    return false;
}
