fn double_the_difference(lst: Vec<f32>) -> i64 {

    let mut sum: i64 = 0;
    for i in 0..lst.len() {
        if (lst[i] - lst[i].round()).abs() < 1e-4 {
            if lst[i] > 0.0 {
                sum += (lst[i].round() as i64) * (lst[i].round() as i64);
            } else {
                sum -= (lst[i].round() as i64) * (lst[i].round() as i64);
            }
        }
    }
    return sum;
